import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    sale_df = df[df['row_kind'] == 'sale'].copy()
except Exception:
    sale_df = df.copy()

try:
    from scipy.stats import chi2_contingency, fisher_exact
    import numpy as np

    carrier_ontime = sale_df.groupby('carrier')['on_time'].agg(['sum', 'count']).reset_index()
    carrier_ontime.columns = ['carrier', 'on_time_sum', 'total']
    carrier_ontime['on_time_rate'] = carrier_ontime['on_time_sum'] / carrier_ontime['total']

    seg_results = []
    for _, row in carrier_ontime.iterrows():
        seg_results.append({"name": str(row['carrier']), "value": float(row['on_time_rate'])})

    result['segments'].append({
        "segment_column": "carrier",
        "metric_column": "on_time",
        "aggregation": "ratio",
        "label": "on_time_delivery",
        "results": seg_results
    })
except Exception:
    pass

try:
    dist_ontime = sale_df.groupby('distance_band')['on_time'].agg(['sum', 'count']).reset_index()
    dist_ontime.columns = ['distance_band', 'on_time_sum', 'total']
    dist_ontime['on_time_rate'] = dist_ontime['on_time_sum'] / dist_ontime['total']

    dist_seg_results = []
    for _, row in dist_ontime.iterrows():
        dist_seg_results.append({"name": str(row['distance_band']), "value": float(row['on_time_rate'])})

    result['segments'].append({
        "segment_column": "distance_band",
        "metric_column": "on_time",
        "aggregation": "ratio",
        "label": "on_time_delivery",
        "results": dist_seg_results
    })
except Exception:
    pass

try:
    cross_df = sale_df.groupby(['carrier', 'distance_band'])['on_time'].agg(['sum', 'count']).reset_index()
    cross_df.columns = ['carrier', 'distance_band', 'on_time_sum', 'total']
    cross_df['on_time_rate'] = cross_df['on_time_sum'] / cross_df['total']

    cross_results = []
    for _, row in cross_df.iterrows():
        cross_results.append({"name": f"{row['carrier']}|{row['distance_band']}", "value": float(row['on_time_rate'])})

    result['segments'].append({
        "segment_column": "carrier|distance_band",
        "metric_column": "on_time",
        "aggregation": "ratio",
        "label": "on_time_delivery",
        "results": cross_results
    })
except Exception:
    pass

try:
    contingency = sale_df.groupby('carrier')['on_time'].agg(
        on_time_yes=lambda x: (x == 1).sum(),
        on_time_no=lambda x: (x == 0).sum()
    ).reset_index()

    carriers = contingency['carrier'].tolist()
    ct_matrix = contingency[['on_time_yes', 'on_time_no']].values

    if ct_matrix.shape[0] == 2:
        stat, p, dof, expected = chi2_contingency(ct_matrix)
        interp = f"Chi-square test of on-time delivery across carriers: chi2={stat:.3f}, p={p:.3g}. "
        if p < 0.05:
            interp += "Significant difference in on-time rates between carriers."
        else:
            interp += "No significant difference in on-time rates between carriers."
        result['statistical_tests'].append({
            "test_name": "chi2_contingency_carrier_ontime",
            "statistic": float(stat),
            "p_value": float(p),
            "interpretation": interp
        })
    else:
        stat, p, dof, expected = chi2_contingency(ct_matrix)
        interp = f"Chi-square test of on-time delivery across carriers: chi2={stat:.3f}, p={p:.3g}. "
        if p < 0.05:
            interp += "Significant difference in on-time rates between carriers."
        else:
            interp += "No significant difference in on-time rates between carriers."
        result['statistical_tests'].append({
            "test_name": "chi2_contingency_carrier_ontime",
            "statistic": float(stat),
            "p_value": float(p),
            "interpretation": interp
        })
except Exception:
    pass

try:
    for dist_val in sale_df['distance_band'].dropna().unique():
        stratum = sale_df[sale_df['distance_band'] == dist_val]
        ct_s = stratum.groupby('carrier')['on_time'].agg(
            on_time_yes=lambda x: (x == 1).sum(),
            on_time_no=lambda x: (x == 0).sum()
        )
        if ct_s.shape[0] < 2:
            continue
        mat = ct_s.values
        stat_s, p_s, _, _ = chi2_contingency(mat)
        interp_s = f"Chi-square within distance_band={dist_val}: chi2={stat_s:.3f}, p={p_s:.3g}. "
        if p_s < 0.05:
            interp_s += "Significant carrier difference within this band."
        else:
            interp_s += "No significant carrier difference within this band."
        result['statistical_tests'].append({
            "test_name": f"chi2_carrier_ontime_within_{dist_val}",
            "statistic": float(stat_s),
            "p_value": float(p_s),
            "interpretation": interp_s
        })
except Exception:
    pass

result['assumptions'].append("Only 'sale' rows included; cancelled and other row_kinds excluded.")
result['assumptions'].append("On-time rate = sum(on_time_flag) / count(shipments with on_time value) per group.")
result['assumptions'].append("Chi-square tests carrier independence from on_time; also run within each distance_band to check Simpson's paradox.")
result['assumptions'].append("on_time is treated as a binary flag (1=on-time, 0=late).")

