        delivered_valid = (row['transit_days'] >= 0)
        if not delivered_valid:
            return None
        if row['days_before_promise'] >= 0:
            return True
        if row['days_late'] > 0:
            return False
        return None

    def in_denominator(row):
        if row['transit_days'] >= 0:
            if row['days_before_promise'] >= 0:
                return True
            if row['days_late'] > 0:
                return True
        status_late = str(row['Status']).strip().lower() in [
            'in transit', 'out for delivery', 'picked up', 'exception',
            'delivery exception', 'delayed', 'tendered', 'booked', 'dispatched',
            'pending', 'shipped', 'partially shipped', 'backordered',
            'short shipped', 'open', 'allocated', 'released', 'picked', 'packed'
        ]
        status_rts = str(row['Status']).strip().lower() in [
            'returned to sender', 'return to sender', 'rts', 'returned', 'refused'
        ]
        if status_rts and row['transit_days'] >= 0:
            return True
        if status_late and row['days_past_due'] > 0:
            return True
        return False

    df_sale['_on_time'] = df_sale.apply(is_on_time, axis=1)
    df_sale['_in_denom'] = df_sale.apply(in_denominator, axis=1)

