import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    sale_mask = (df['row_kind'] == 'sale') & (df['Currency'] == 'USD')
    df_sale = df[sale_mask].copy()

    last_ship_date = df_sale['Ship Date'].max()

    def is_on_time(row):
        dbp = row['days_before_promise']
        td = row['transit_days']
        dpd = row['days_past_due']
        status = str(row['Status']).strip().lower()
        rts_statuses = {'returned to sender', 'return to sender', 'rts', 'returned', 'refused'}
        late_open_statuses = {
            'in transit', 'out for delivery', 'picked up', 'exception',
            'delivery exception', 'delayed', 'tendered', 'booked', 'dispatched',
            'pending', 'shipped', 'partially shipped', 'backordered',
            'short shipped', 'open', 'allocated', 'released', 'picked', 'packed'
        }
        if pd.notna(td) and td >= 0 and pd.notna(dbp) and dbp >= 0:
            return 'numerator'
        days_late = row['days_late']
        if pd.notna(td) and td >= 0 and pd.notna(days_late) and days_late > 0:
            return 'denominator'
        if pd.notna(row['Promised Date']) and status in rts_statuses and pd.notna(td) and td >= 0:
            return 'denominator'
        if pd.notna(dpd) and dpd > 0 and status in late_open_statuses:
            return 'denominator'
        return 'exclude'

    df_sale['_otd_role'] = df_sale.apply(is_on_time, axis=1)

    df_otd = df_sale[df_sale['_otd_role'].isin(['numerator', 'denominator'])].copy()
    df_otd['_is_ontime'] = (df_otd['_otd_role'] == 'numerator').astype(int)

    carrier_groups = df_otd.groupby('Carrier')
    carrier_results = []
    for carrier, grp in carrier_groups:
        numerator = grp['_is_ontime'].sum()
        denominator = len(grp)
        rate = numerator / denominator if denominator > 0 else float('nan')
        carrier_results.append({"name": str(carrier), "value": round(float(rate), 6)})

    carrier_results_sorted = sorted(carrier_results, key=lambda x: x['value'], reverse=True)

    overall_num = df_otd['_is_ontime'].sum()
    overall_den = len(df_otd)
    overall_rate = overall_num / overall_den if overall_den > 0 else float('nan')

    result['segments'].append({
        "segment_column": "Carrier",
        "metric_column": "Delivered At",
        "aggregation": "ratio",
        "label": "on_time_delivery",
        "results": carrier_results_sorted
    })

    result['segments'].append({
        "segment_column": "Carrier",
        "metric_column": "Delivered At",
        "aggregation": "ratio",
        "label": "on_time_delivery_overall",
        "results": [{"name": "Overall", "value": round(float(overall_rate), 6)}]
    })

    result['assumptions'].append(
        f"On-time delivery denominator includes delivered-on-time, late-delivered, RTS, and open-past-due shipments; {overall_den} shipments in scope."
    )
    result['assumptions'].append(
        f"Cancelled ({df[df['row_kind']=='cancelled'].shape[0]}) and non-USD ({df[df['Currency']!='USD'].shape[0]}) rows excluded."
    )
    result['assumptions'].append(
        "days_before_promise and days_late columns used as provided; transit_days used for delivered-row filter."
    )

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

